    65→body {
    66→  font-family: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
    67→  font-weight: 400;
    68→  line-height: 1.5;
    69→  color: var(--color-text);
    70→  background-color: var(--color-surface);
    71→  margin: 0;
