   124→.btn {
   125→  display: inline-flex;
   126→  align-items: center;
   127→  justify-content: center;
   128→  gap: 8px;
   129→  padding: 12px 24px;
   130→  font-family: inherit;
   131→  font-size: 0.9375rem;
   132→  font-weight: 600;
   133→  line-height: 1;
   134→  text-align: center;
   135→  white-space: nowrap;
   136→  border: none;
   137→  border-radius: var(--radius-lg);
   138→  cursor: pointer;
   139→  transition: all var(--transition-fast);
   140→
   141→  &:disabled {
   142→    opacity: 0.5;
   143→    cursor: not-allowed;
   144→  }
   145→
   146→  svg {
   147→    width: 20px;
   148→    height: 20px;
   149→  }
   150→}
