   157→    background-color: #333;
   158→  }
   159→}
   160→
   161→.btn-secondary {
   162→  background-color: var(--color-white);
   163→  color: var(--color-primary);
   164→  border: 1px solid var(--color-border);
   165→
   166→  &:hover:not(:disabled) {
   167→    background-color: var(--color-surface);
   168→  }
   169→}
   170→
   171→.btn-icon {
   172→  width: 48px;
   173→  height: 48px;
   174→  padding: 0;
   175→  border-radius: var(--radius-md);
   176→  background-color: var(--color-surface-dark);
   177→  color: var(--color-text);
   178→  border: none;
   179→
   180→  &:hover:not(:disabled) {
   181→    background-color: var(--color-border);
   182→  }
   183→
   184→  svg {
   185→    width: 24px;
   186→    height: 24px;
   187→  }
   188→}
   189→
   190→.btn-notify {
   191→  background-color: var(--color-text-muted);
   192→  color: var(--color-white);
   193→
   194→  &:hover:not(:disabled) {
   195→    background-color: var(--color-text);
   196→  }
   197→}
   198→
   199→.btn-notify-active {
   200→  background-color: #22c55e;
   201→  color: var(--color-white);
   202→  cursor: default;
   203→
   204→  &:disabled {
   205→    opacity: 1;
   206→    background-color: #22c55e;
   207→  }
   208→}
