   210→/* ============================================
   211→   Form Elements
   212→   ============================================ */
   213→.input {
   214→  width: 100%;
   215→  padding: 12px 16px;
   216→  font-family: inherit;
   217→  font-size: 0.9375rem;
   218→  color: var(--color-text);
   219→  background-color: var(--color-white);
   220→  border: 1px solid var(--color-border);
   221→  border-radius: var(--radius-md);
   222→  transition: border-color var(--transition-fast);
   223→
   224→  &::placeholder {
   225→    color: var(--color-text-light);
