   238→  border-radius: var(--radius-lg);
   239→  overflow: hidden;
   240→}
   241→
   242→/* ============================================
   243→   Rating Stars
   244→   ============================================ */
   245→.rating {
   246→  display: inline-flex;
   247→  align-items: center;
   248→  gap: 2px;
   249→
   250→  svg {
   251→    width: 16px;
   252→    height: 16px;
   253→  }
   254→
   255→  &-star {
   256→    color: #fbbf24;
   257→  }
   258→
   259→  &-star-empty {
   260→    color: var(--color-border);
   261→  }
   262→}
   263→
   264→/* ============================================
   265→   Utilities
   266→   ============================================ */
   267→.visually-hidden {
   268→  position: absolute;
   269→  width: 1px;
   270→  height: 1px;
   271→  padding: 0;
   272→  margin: -1px;
   273→  overflow: hidden;
   274→  clip: rect(0, 0, 0, 0);
   275→  white-space: nowrap;
   276→  border: 0;
   277→}
   278→
   279→/* Scrollbar styling */
   280→::-webkit-scrollbar {
   281→  width: 8px;
   282→  height: 8px;
   283→}
   284→
   285→::-webkit-scrollbar-track {
   286→  background: var(--color-surface);
   287→}
   288→
   289→::-webkit-scrollbar-thumb {
   290→  background: var(--color-border);
   291→  border-radius: 4px;
   292→
   293→  &:hover {
   294→    background: var(--color-text-light);
   295→  }
   296→}
   297→
   298→/* ============================================
   299→   Animations
   300→   ============================================ */
   301→@keyframes fadeIn {
   302→  from { opacity: 0; }
   303→  to { opacity: 1; }
   304→}
   305→
   306→@keyframes slideUp {
   307→  from {
   308→    opacity: 0;
   309→    transform: translateY(10px);
   310→  }
   311→  to {
   312→    opacity: 1;
   313→    transform: translateY(0);
   314→  }
   315→}
   316→
   317→@keyframes slideDown {
   318→  from {
   319→    opacity: 0;
   320→    transform: translateY(-10px);
   321→  }
   322→  to {
   323→    opacity: 1;
   324→    transform: translateY(0);
   325→  }
   326→}
   327→
   328→.animate-fade-in {
   329→  animation: fadeIn 0.3s ease-out;
   330→}
   331→
   332→.animate-slide-up {
   333→  animation: slideUp 0.3s ease-out;
   334→}
   335→
   336→.animate-slide-down {
   337→  animation: slideDown 0.3s ease-out;
   338→}
